import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import {
  planBatch,
  chunkForGeminiCalls,
  parsePageRange,
  BatchValidationError,
  PER_CALL_PAGE_CAP,
  GEMINI_BATCH_SIZE,
} from '../src/tools/gemini_ocr_batching.js';

describe('parsePageRange', () => {
  test('undefined range returns all pages 1..totalPages', () => {
    assert.deepEqual(parsePageRange(undefined, 5), [1, 2, 3, 4, 5]);
  });

  test('single dash range', () => {
    assert.deepEqual(parsePageRange('2-4', 10), [2, 3, 4]);
  });

  test('comma + range mix, deduped and sorted', () => {
    assert.deepEqual(parsePageRange('5,7,9-12,7', 20), [5, 7, 9, 10, 11, 12]);
  });

  test('single page number', () => {
    assert.deepEqual(parsePageRange('3', 10), [3]);
  });

  test('rejects page beyond document length', () => {
    assert.throws(() => parsePageRange('1-20', 10), BatchValidationError);
  });

  test('rejects malformed segment', () => {
    assert.throws(() => parsePageRange('abc', 10), BatchValidationError);
  });

  test('rejects descending range', () => {
    assert.throws(() => parsePageRange('9-3', 10), BatchValidationError);
  });
});

describe('planBatch', () => {
  test('exact multiple of cap -> no truncation', () => {
    const pages = Array.from({ length: 10 }, (_, i) => i + 1);
    const plan = planBatch(pages, 0, 10);
    assert.equal(plan.truncated, false);
    assert.equal(plan.pagesToProcess.length, 10);
    assert.equal(plan.truncationMessage, undefined);
  });

  test('remainder batch -> truncated with correct message', () => {
    const pages = Array.from({ length: 40 }, (_, i) => i + 1); // 1..40
    const plan = planBatch(pages, 0, 12); // cap 12 of 40
    assert.equal(plan.truncated, true);
    assert.equal(plan.pagesToProcess.length, 12);
    assert.equal(plan.nextStartIndex, 12);
    assert.equal(
      plan.truncationMessage,
      '12 of 40 pages processed; call again with page_range starting at page 13.',
    );
  });

  test('task-spec example: 12 of 40', () => {
    const pages = Array.from({ length: 40 }, (_, i) => i + 1);
    const plan = planBatch(pages, 0, 12);
    assert.equal(
      plan.truncationMessage,
      '12 of 40 pages processed; call again with page_range starting at page 13.',
    );
  });

  test('single page request', () => {
    const plan = planBatch([7], 0, 40);
    assert.equal(plan.truncated, false);
    assert.deepEqual(plan.pagesToProcess, [7]);
  });

  test('cap larger than total -> no truncation', () => {
    const pages = [1, 2, 3];
    const plan = planBatch(pages, 0, 100);
    assert.equal(plan.truncated, false);
    assert.deepEqual(plan.pagesToProcess, [1, 2, 3]);
  });

  test('already_processed_count beyond total is a validation error', () => {
    assert.throws(() => planBatch([1, 2, 3], 5, 10), BatchValidationError);
  });

  test('already_processed_count === total returns empty plan, not truncated', () => {
    const plan = planBatch([1, 2, 3], 3, 10);
    assert.deepEqual(plan.pagesToProcess, []);
    assert.equal(plan.truncated, false);
  });

  test('follow-up call after truncation resumes from nextStartIndex', () => {
    const pages = Array.from({ length: 40 }, (_, i) => i + 1);
    const first = planBatch(pages, 0, 12);
    const second = planBatch(pages, first.nextStartIndex!, 12);
    assert.deepEqual(second.pagesToProcess, pages.slice(12, 24));
    assert.equal(second.truncated, true);
  });

  test('empty requestedPages throws', () => {
    assert.throws(() => planBatch([], 0, 10), BatchValidationError);
  });

  test('default PER_CALL_PAGE_CAP is used when cap omitted', () => {
    const pages = Array.from({ length: PER_CALL_PAGE_CAP + 5 }, (_, i) => i + 1);
    const plan = planBatch(pages, 0);
    assert.equal(plan.truncated, true);
    assert.equal(plan.pagesToProcess.length, PER_CALL_PAGE_CAP);
  });
});

describe('chunkForGeminiCalls', () => {
  test('splits into GEMINI_BATCH_SIZE chunks by default', () => {
    const pages = Array.from({ length: 13 }, (_, i) => i + 1);
    const chunks = chunkForGeminiCalls(pages);
    assert.equal(chunks.length, Math.ceil(13 / GEMINI_BATCH_SIZE));
    assert.deepEqual(chunks.flat(), pages);
    for (const c of chunks.slice(0, -1)) assert.equal(c.length, GEMINI_BATCH_SIZE);
  });

  test('custom batch size', () => {
    const chunks = chunkForGeminiCalls([1, 2, 3, 4, 5], 2);
    assert.deepEqual(chunks, [[1, 2], [3, 4], [5]]);
  });

  test('empty input -> no chunks', () => {
    assert.deepEqual(chunkForGeminiCalls([]), []);
  });

  test('rejects non-positive batch size', () => {
    assert.throws(() => chunkForGeminiCalls([1, 2, 3], 0), BatchValidationError);
  });
});
